// 過濾 + 去重 + 攤平成好用的欄位。
//
// 為什麼把三件事放同一個節點：後面的 "整理回覆並切段" 要靠索引位置對回
// chat id,中間多一個 IF 節點會讓 items 數量改變、索引對不上。

const staticData = $getWorkflowStaticData('global');
staticData.seenUpdates = staticData.seenUpdates || [];

const out = [];

for (const item of $input.all()) {
  const update = item.json;
  const message = update.message;

  // 貼圖、照片、加入群組通知都會進來,沒有 text 的一律跳過
  if (!message || typeof message.text !== 'string' || message.text.trim() === '') continue;

  // Telegram 沒收到 200 就會重送同一個 update_id
  const id = String(update.update_id);
  if (staticData.seenUpdates.includes(id)) continue;
  staticData.seenUpdates.push(id);

  out.push({
    json: {
      updateId: update.update_id,
      // ★ 回訊息要用 chat.id,不是 from.id。群組裡兩者不同。
      chatId: message.chat.id,
      chatType: message.chat.type,
      userId: message.from?.id ?? null,
      userName: message.from?.username ?? message.from?.first_name ?? 'unknown',
      text: message.text.trim(),
      messageId: message.message_id,
    },
  });
}

// static data 只在執行結束後寫回,而且 queue mode 多 worker 不共享。
// 流量大的正式環境請改用 Redis SET NX EX 或 DB 的 unique index。
staticData.seenUpdates = staticData.seenUpdates.slice(-500);

return out;

// 把後端回覆整理成可以直接送出的多則訊息。

const TELEGRAM_LIMIT = 4096;
const FALLBACK = '抱歉,系統忙線中,請稍後再試一次。';

function splitMessage(text, limit = TELEGRAM_LIMIT) {
  const chars = Array.from(String(text ?? ''));
  if (chars.length === 0) return [];
  if (chars.length <= limit) return [chars.join('')];

  const chunks = [];
  let rest = chars;

  while (rest.length > limit) {
    const windowText = rest.slice(0, limit).join('');
    let cut = -1;

    for (const [pattern, minRatio] of [
      [/\n\n/g, 0.3],
      [/\n/g, 0.3],
      [/[。！？!?](?=\s|$)/g, 0.5],
      [/\s/g, 0.7],
    ]) {
      let last = -1;
      for (const m of windowText.matchAll(pattern)) last = m.index + m[0].length;
      if (last > limit * minRatio) { cut = Array.from(windowText.slice(0, last)).length; break; }
    }
    if (cut <= 0) cut = limit;

    chunks.push(rest.slice(0, cut).join('').trimEnd());
    rest = rest.slice(cut);
    while (rest.length && /\s/.test(rest[0])) rest = rest.slice(1);
  }
  if (rest.length) chunks.push(rest.join('').trimEnd());
  return chunks.filter((c) => c.length > 0);
}

// HTTP 節點開了 fullResponse,所以輸出是 { body, headers, statusCode }。
// 它的 items 跟 "接收、去重、過濾" 一對一且同序,所以可以用索引對回 chatId。
const sources = $('接收、去重、過濾').all();
const out = [];

$input.all().forEach((item, i) => {
  const chatId = sources[i]?.json.chatId;
  if (chatId === undefined) return;

  const status = item.json.statusCode ?? 200;
  const ok = status >= 200 && status < 300;
  const reply = ok ? (item.json.body?.reply ?? '') : '';

  // 後端掛掉也要給使用者一個交代,不能讓訊息石沉大海
  const text = reply.trim() === '' ? FALLBACK : reply;

  splitMessage(text).forEach((chunk, part) => {
    out.push({ json: { chatId, text: chunk, part: part + 1, backendStatus: status } });
  });
});

return out;
